  src: url("../fonts/jetbrains-mono-latin-400-normal.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}
@theme {
  --font-sans: Inter, Arial, sans-serif;
  --font-mono: "JetBrains Mono", monospace;
}
:root {
  color-scheme: light;
  --bg: #fff;
  --surface: #f5f5f4;
  --text: #202124;
  --muted: #575b63;
  --link: #a12a2a;
  --focus: #005fcc;
  --line: #d9dbdf;
  --selected: #faeeee;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #171819;
    --surface: #222426;
    --text: #f1f2f3;
    --muted: #b6bbc2;
    --link: #ffa8a3;
    --focus: #8dbbff;
    --line: #414448;
    --selected: #352526;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #171819;
  --surface: #222426;
  --text: #f1f2f3;
  --muted: #b6bbc2;
  --link: #ffa8a3;
  --focus: #8dbbff;
  --line: #414448;
  --selected: #352526;
}
* {
  box-sizing: border-box;
}
html {
  scroll-padding-top: 6rem;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-optical-sizing: auto;
  font-size: 1.0625rem;
  line-height: 1.65;
}
a {
  color: var(--link);
  text-underline-offset: 0.2em;
}
a:hover {
  text-decoration-thickness: 2px;
}
button,
input,
select,
summary {
  font: inherit;
}
button,
select {
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.25rem;
  min-height: 2.75rem;
  padding: 0.4rem 0.75rem;
}
button,
summary,
select {
  cursor: pointer;
}
button:hover {
  border-color: var(--muted);
}
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}
[hidden] {
  display: none !important;
}
.skip {
  position: fixed;
  top: -10rem;
  left: 1rem;
  z-index: 20;
  background: var(--bg);
  padding: 1rem;
}
.skip:focus {
  top: 1rem;
}
.topbar {
  height: 4.5rem;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  gap: 1rem;
  background: var(--bg);
  position: sticky;
  top: 0;
  z-index: 5;
}
.brand {
  font-weight: 750;
  font-size: 1.5rem;
  text-decoration: none;
  color: var(--text);
  white-space: nowrap;
}
.brand span {
  font-size: 0.9375rem;
  font-weight: 450;
  margin-left: 1rem;
  color: var(--muted);
}
.tools {
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 0.875rem;
}
.tools a {
  padding: 0.5rem;
}
.theme-control {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}
kbd {
  font-size: 0.75rem;
  color: var(--muted);
  margin-left: 0.5rem;
}
.shell {
  max-width: 100rem;
  margin: auto;
  display: grid;
  grid-template-columns: 15rem minmax(0, 1fr) 11.25rem;
  gap: 3rem;
  padding: 0 2rem;
}
.sidebar {
  font-size: 0.9375rem;
  line-height: 1.5;
  border-right: 1px solid var(--line);
  padding-right: 1.5rem;
}
.navigation {
  position: sticky;
  top: 4.5rem;
  max-height: calc(100dvh - 4.5rem);
  overflow: auto;
  padding: 2rem 0;
}
.navigation > summary {
  display: none;
}
.navigation:not([open]) > nav {
  display: block;
}
.nav-group {
  margin-bottom: 1.5rem;
}
.nav-group h2 {
  font-size: 0.75rem;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.055em;
  color: var(--muted);
  margin: 0 0 0.5rem 0.75rem;
}
.nav-group a {
  display: block;
  text-decoration: none;
  padding: 0.375rem 0.75rem;
  border-left: 2px solid transparent;
  color: var(--muted);
  min-height: 2rem;
}
.nav-group a:hover {
  color: var(--text);
  background: var(--surface);
}
.nav-group a[aria-current] {
  color: var(--link);
  border-left-color: var(--link);
  background: var(--selected);
  font-weight: 600;
}
.shell main {
  min-width: 0;
  padding: 3rem 0 2rem;
}
article {
  max-width: 52rem;
  margin: 0 auto;
}
.article-meta {
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
}
.prose h1 {
  font-size: 2.5rem;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: -0.035em;
  margin: 0 0 1.5rem;
}
.prose h2 {
  font-size: 1.75rem;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.02em;
  margin: 3rem 0 1rem;
  scroll-margin-top: 6rem;
}
.prose h3 {
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.35;
  margin: 2rem 0 0.75rem;
}
.prose h4 {
  font-weight: 600;
  margin: 1.5rem 0 0.5rem;
}
.prose p {
  max-width: 65ch;
  margin: 1rem 0;
}
.prose > h1 + p {
  font-size: 1.125rem;
  color: var(--muted);
  margin-bottom: 2rem;
}
.prose ul,
.prose ol {
  padding-left: 1.5rem;
  margin: 1rem 0;
  max-width: 65ch;
}
.prose ul {
  list-style: disc;
}
.prose ol {
  list-style: decimal;
}
.prose li {
  padding-left: 0.25rem;
  margin: 0.5rem 0;
}
.prose li ul,
.prose li ol {
  margin: 0.5rem 0;
}
.prose blockquote {
  border-left: 3px solid var(--link);
  padding: 0.25rem 1.5rem;
  margin: 1.5rem 0;
  color: var(--muted);
  background: var(--surface);
}
code,
pre {
  font-family: var(--font-mono);
  font-variant-ligatures: none;
  font-feature-settings:
    "liga" 0,
    "calt" 0;
}
code {
  font-size: 0.88235em;
  overflow-wrap: anywhere;
}
p code,
li code,
td code {
  background: var(--surface);
  padding: 0.1rem 0.25rem;
  border-radius: 0.15rem;
}
pre {
  background: var(--surface);
  border: 1px solid var(--line);
  padding: 1.5rem;
  overflow: auto;
  max-width: 100%;
  font-size: 0.9375rem;
  line-height: 1.6;
  margin: 1.5rem 0;
  tab-size: 4;
}
pre code {
  font-size: inherit;
  overflow-wrap: normal;
}
.icon {
